// Etsy Receipt → orders-Schema transformieren
// Gibt eine flache Liste zurück; ein nachgelagerter IF-Node trennt
// erlaubte Währungen (→ upsert) von unerwarteten (→ Stop & Error).

const ALLOWED_CURRENCIES = new Set(['EUR']);

const results = $input.all()[0]?.json.results ?? [];

const money = (obj) => obj ? (obj.amount / obj.divisor) : null;

// Etsy liefert Texte HTML-kodiert ("Mother&#39;s Day") – sonst landet das
// so auf Rechnung, Lieferschein und in Notion.
const decodeHtml = (s) => s == null ? null : String(s)
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&amp;/g, '&');

// Etsy-Status kommt je nach Endpoint groß- oder kleingeschrieben
// ("Paid", "Completed") → lowercase vergleichen.
const statusMap = {
  'paid':               'paid',
  'open':               'paid',
  'payment processing': 'paid',
  'completed':          'completed',
  'shipped':            'shipped',
  'canceled':           'cancelled',
  'cancelled':          'cancelled',
  'fully refunded':     'cancelled',
};

const orders = [];

for (const r of results) {
  const currency = r.grandtotal?.currency_code
                ?? r.total_price?.currency_code
                ?? r.subtotal?.currency_code
                ?? r.currency_code
                ?? 'UNKNOWN';

  const items = (r.transactions ?? []).map(t => ({
    listing_id: t.listing_id,
    title:      decodeHtml(t.title),
    quantity:   t.quantity,
    price:      money(t.price),
    is_digital: t.is_digital ?? false,
  }));

  // Zweite Adresszeile (Hinterhaus, c/o, Apartment) gehört auf den
  // Lieferschein; "\n" wird in den Typst-Templates als Zeilenumbruch gesetzt.
  const street = [r.first_line, r.second_line]
    .map(decodeHtml)
    .filter(Boolean)
    .join('\n') || null;

  // Letzte Sendung mit Trackingnummer (wird beim Versand in Etsy erfasst)
  const shipment = (r.shipments ?? []).filter(s => s.tracking_code).at(-1);

  orders.push({
    json: {
      order_id:      String(r.receipt_id),
      source:        'etsy',
      order_date:    new Date(r.created_timestamp * 1000).toISOString(),
      buyer_name:    decodeHtml(r.name),
      buyer_email:   r.buyer_email ?? null,
      buyer_street:  street,
      buyer_city:    decodeHtml(r.city),
      buyer_zip:     r.zip ?? null,
      buyer_country: r.country_iso ?? null,
      items_json:    JSON.stringify(items),
      subtotal:      money(r.subtotal),
      shipping_cost: money(r.total_shipping_cost),
      total:         money(r.grandtotal),
      currency,
      status:        statusMap[String(r.status ?? '').toLowerCase()]
                       ?? (r.is_shipped ? 'completed' : 'paid'),
      is_digital:    items.every(i => i.is_digital),
      tracking_number: shipment?.tracking_code ?? null,
      carrier:         shipment ? decodeHtml(shipment.carrier_name) : null,
      currency_allowed: ALLOWED_CURRENCIES.has(currency),
      // Für den Sync-Cursor (min_last_modified beim nächsten Lauf)
      etsy_updated_ts: r.updated_timestamp ?? r.update_timestamp ?? r.created_timestamp,
    }
  });
}

return orders;

